import { setTimeout as wait } from "node:timers/promises";
import { interruption } from "./private.mjs";
import { retryAttempts } from "./retry.mjs";
import { createResponsesSession } from "@katalon-experiments/ai-client/responses-session";

import { storeTestAgentResponses } from "@katalon-experiments/ai-client/agents";

export function createComputerAgentResponsesSession(options) {
  return createResponsesSession({
    ...options,
    storeResponses: storeTestAgentResponses,
  });
}

export const defaultExecutionCallLimit = 80;

export function executionLimitReason(deadline, calls, callLimit) {
  if (Date.now() >= deadline) return "Time limit";
  if (calls >= callLimit) return "API call limit";
}

// fetch has no retry API. Keep policy here, where each attempt can be retained
// and charged as unknown without replaying the surrounding browser loop.
export const providerRetryPolicy = Object.freeze({
  maxAttempts: 3,
  backoffMs: [1000, 2000],
  maxRetryAfterMs: 30000,
  requestTimeoutMs: 120000,
});

/** Retain only failure metadata. Request and response bodies stay out of diagnostics. */
export function createProviderErrorLog(save) {
  const failures = [];
  return async (
    phase,
    call,
    {
      attempt = 1,
      httpStatus,
      error,
      responseRejected,
      at = new Date().toISOString(),
    },
  ) => {
    const kind =
      error !== undefined
        ? "request-error"
        : httpStatus < 200 || httpStatus >= 300
          ? "http-error"
          : responseRejected
            ? "response-error"
            : undefined;
    if (!kind) return;
    failures.push({
      phase,
      call,
      attempt,
      at,
      kind,
      ...(httpStatus === undefined ? {} : { httpStatus }),
    });
    await save("provider-errors.json", failures);
  };
}

export function providerRetryDelay(value, attempt) {
  const seconds = value === undefined ? NaN : Number(value);
  const date = Date.parse(value);
  const requested = Number.isFinite(seconds)
    ? seconds * 1000
    : Number.isFinite(date)
      ? date - Date.now()
      : 0;
  return Math.max(
    providerRetryPolicy.backoffMs[attempt - 1],
    Math.min(providerRetryPolicy.maxRetryAfterMs, Math.max(0, requested)),
  );
}

export function waitForProviderRetry(delayMs, signal, deadline = Infinity) {
  const remaining = Number.isFinite(deadline)
    ? AbortSignal.timeout(Math.max(1, deadline - Date.now()))
    : undefined;
  return wait(delayMs, undefined, {
    signal:
      signal && remaining
        ? AbortSignal.any([remaining, signal])
        : (signal ?? remaining),
  });
}

function check(signal, deadline) {
  if (signal?.aborted) throw new Error(interruption(signal).reason);
  if (Date.now() >= deadline) throw new Error("Time limit");
}

/** Share one attempt budget for HTTP failures and caller-selected response recovery. */
export async function requestProvider({
  api,
  apiKey,
  request,
  requestAI,
  managedCore,
  signal,
  deadline,
  remainingAttempts = providerRetryPolicy.maxAttempts,
  headersFor,
  record,
  retryResponseReason,
  beforeAttempt,
}) {
  const serialized = JSON.stringify(request);
  const maxAttempts = Math.min(
    providerRetryPolicy.maxAttempts,
    remainingAttempts,
  );
  return retryAttempts(maxAttempts, async (attempt, canRetry) => {
    await beforeAttempt?.();
    check(signal, deadline);
    const started = Date.now();
    const row = { attempt, at: new Date(started).toISOString() };
    const timeout = AbortSignal.timeout(
      Math.max(
        1,
        Math.min(providerRetryPolicy.requestTimeoutMs, deadline - started),
      ),
    );
    const requestSignal = signal ? AbortSignal.any([timeout, signal]) : timeout;
    let response, bodyText, body;
    try {
      // Preserve the selected host transport; failures never switch routes.
      // A fresh copy keeps a host adapter from mutating a later attempt's input.
      response = requestAI
        ? await requestAI(JSON.parse(serialized), requestSignal)
        : await fetch(api, {
            method: "POST",
            redirect: "error",
            headers: {
              Authorization: `Bearer ${apiKey}`,
              "Content-Type": "application/json",
            },
            body: serialized,
            signal: requestSignal,
          });
      row.httpStatus = response.status;
      row.headers = headersFor(response);
      bodyText = await response.text();
      try {
        body = JSON.parse(bodyText);
      } catch {
        // Non-JSON errors (for example a proxy 502 page) are still HTTP errors.
        if (response.ok) throw new Error("Provider returned invalid JSON");
      }
    } catch (error) {
      row.durationMs = Date.now() - started;
      row.error = String(error);
      await record({ row, bodyText, body });
      check(signal, deadline);
      throw error;
    }
    row.durationMs = Date.now() - started;
    const managedNonRetryable =
      managedCore === true &&
      requestAI &&
      ((response.status === 429 &&
        body?.statusCode === 429 &&
        body.code === "ai_gateway_rejected" &&
        body.retryable === false) ||
        (response.status === 409 &&
          body?.error === "ai_continuation_unavailable"));
    const responseRetryReason = response.ok
      ? retryResponseReason?.(body)
      : undefined;
    if (responseRetryReason) row.responseRejected = true;
    const retryable =
      !managedNonRetryable &&
      ([408, 409, 429].includes(response.status) ||
        (response.status >= 500 && response.status <= 599) ||
        Boolean(responseRetryReason));
    if (retryable && canRetry)
      row.retry = {
        delayMs: providerRetryDelay(row.headers["retry-after"], attempt),
        status: "waiting",
        ...(responseRetryReason && { reason: responseRetryReason }),
      };
    await record({ row, bodyText, body });
    if (!row.retry) {
      check(signal, deadline);
      return { result: { response, body, row } };
    }
    return {
      retry: true,
      beforeRetry: async () => {
        const waitStarted = Date.now();
        try {
          check(signal, deadline);
          await waitForProviderRetry(row.retry.delayMs, signal, deadline);
          check(signal, deadline);
          row.retry.status = "returned";
        } catch (error) {
          row.retry.status = "interrupted";
          row.retry.error = String(error);
          throw error;
        } finally {
          row.retry.actualDelayMs = Date.now() - waitStarted;
          await record({ row, bodyText, body, update: true });
        }
      },
    };
  });
}
